// SPDX-License-Identifier: ekubo-license-v1.eth
pragma solidity >=0.8.30;

import {CallPoints} from "../src/types/callPoints.sol";
import {PoolKey} from "../src/types/poolKey.sol";
import {FullTest, MockExtension} from "./FullTest.sol";
import {RouteNode, TokenAmount} from "../src/Router.sol";
import {SqrtRatio} from "../src/types/sqrtRatio.sol";
import {PoolBalanceUpdate} from "../src/types/poolBalanceUpdate.sol";
import {MIN_TICK, MAX_TICK} from "../src/math/constants.sol";
import {MIN_SQRT_RATIO, MAX_SQRT_RATIO} from "../src/types/sqrtRatio.sol";
import {Positions} from "../src/Positions.sol";
import {tickToSqrtRatio} from "../src/math/ticks.sol";
import {computeFee} from "../src/math/fee.sol";
import {CoreLib} from "../src/libraries/CoreLib.sol";
import {console} from "forge-std/console.sol";
import {TestToken} from "./TestToken.sol";
import {Core} from "../src/Core.sol";
import {Test} from "forge-std/Test.sol";
import {PositionId, createPositionId} from "../src/types/positionId.sol";
import {tickToSqrtRatio} from "../src/math/ticks.sol";
import {maxLiquidity, liquidityDeltaToAmountDelta} from "../src/math/liquidity.sol";
import {SqrtRatio} from "../src/types/sqrtRatio.sol";
import {PoolState} from "../src/types/poolState.sol";
import {CoreStorageLayout} from "../src/libraries/CoreStorageLayout.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {Position} from "../src/types/position.sol";
import {StorageSlot} from "../src/types/storageSlot.sol";
import {PoolId} from "../src/types/poolId.sol";
import {SafeCastLib} from "../lib/solady/src/utils/SafeCastLib.sol";
import {TokenWrapper} from "../src/TokenWrapper.sol";
import {TokenWrapperFactory} from "../src/TokenWrapperFactory.sol";

contract PoC is FullTest {
    address alice = makeAddr("alice");
    address bob = makeAddr("bob");

    function testMissingDeadlineProtection(
        CallPoints memory callPoints
    ) public {
        // SET UP
        PoolKey memory poolKey = createPool(0, 1 << 63, 100, callPoints);

        // GIVE USERS TOKENS
        token0.transfer(alice, 500);
        token1.transfer(alice, 500);
        token0.transfer(bob, 1000);
        token1.transfer(bob, 1000);

        vm.startPrank(alice);
        token0.approve(address(positions), 500);
        token1.approve(address(positions), 500);

        // 1. ALICE PREPARES TRANSACTION AT FAVOURABLE PRICES
        // SNAPSHOT: SHOWS LIQUIDITY TOKENS ALICE WOULD HAVE GOT
        uint256 snapshot = vm.snapshot();
        (, uint128 expectedLiquidity, , ) = positions.mintAndDeposit(
            poolKey,
            -100,
            100,
            500,
            500,
            0
        );

        console.log("EXPECTED AT SUBMISSION: ", expectedLiquidity);

        vm.revertTo(snapshot);
        vm.stopPrank();

        // 2. TRANSACTION SITS IN MEMPOOL
        // DURING THIS TIME, MARKET CONDITIONS CHANGE
        vm.warp(block.timestamp + 2 hours);

        // 3. ANOTHER USERS SWAP MOVES PRICE UNFAVOURABLY
        vm.startPrank(bob);
        token0.approve(address(router), 1000);
        router.swap(poolKey, false, 1000, SqrtRatio.wrap(0), 0, 0, bob);
        vm.stopPrank();

        // 4. ORIGINAL TRANSACTION EXECUTES AT WORSE PRICE
        vm.startPrank(alice);
        (, uint128 actualLiquidity, , ) = positions.mintAndDeposit(
            poolKey,
            -100,
            100,
            500,
            500,
            0
        );

        console.log("ACTUAL AT EXECUTION:", actualLiquidity);
        console.log("LOSS:", (expectedLiquidity - actualLiquidity));
        assertLt(actualLiquidity, expectedLiquidity);

        // WITH DEADLINE: TRANSACTION WOULD HAVE BEEN REVERTED AFTER SET TIME
        // PROTECTING USER FROM STALE EXECUTION
        vm.stopPrank();
    }
}
